const test = require("node:test");
const assert = require("node:assert");

const { startServer, api, store } = require("./helpers");

async function seed(base) {
  for (const slug of ["alpha", "beta", "gamma", "delta"]) {
    await api(base, "POST", "/api/links", { url: `https://example.com/${slug}`, slug });
  }
  const click = (slug, n) => {
    for (let i = 0; i < n; i++) store.recordClick(slug, "2026-07-01T10:00:00.000Z");
  };
  click("alpha", 2);
  click("beta", 5);
  click("gamma", 2);
  // delta: 0 clicks
}

test("top links ranked by clicks desc, ties by slug asc", async () => {
  const { base, close } = startServer();
  try {
    await seed(base);
    const top = await api(base, "GET", "/api/links/top");
    assert.strictEqual(top.status, 200);
    assert.deepStrictEqual(
      top.json.map((e) => [e.slug, e.clicks]),
      [["beta", 5], ["alpha", 2], ["gamma", 2], ["delta", 0]],
    );
    assert.strictEqual(top.json[0].url, "https://example.com/beta");
  } finally {
    await close();
  }
});

test("limit trims the list", async () => {
  const { base, close } = startServer();
  try {
    await seed(base);
    const top2 = await api(base, "GET", "/api/links/top?limit=2");
    assert.deepStrictEqual(top2.json.map((e) => e.slug), ["beta", "alpha"]);
  } finally {
    await close();
  }
});

test("invalid limits are rejected", async () => {
  const { base, close } = startServer();
  try {
    await seed(base);
    for (const bad of ["0", "-3", "51", "abc", "2.5"]) {
      const resp = await api(base, "GET", `/api/links/top?limit=${bad}`);
      assert.strictEqual(resp.status, 400, `limit=${bad} should 400, got ${resp.status}`);
    }
  } finally {
    await close();
  }
});

test("existing /:slug lookups are not broken by the new route", async () => {
  const { base, close } = startServer();
  try {
    await seed(base);
    const one = await api(base, "GET", "/api/links/alpha");
    assert.strictEqual(one.status, 200);
    assert.strictEqual(one.json.slug, "alpha");
    assert.strictEqual((await api(base, "GET", "/api/links/nope")).status, 404);
  } finally {
    await close();
  }
});

